import os
from typing import List, Dict, Any, Tuple

import requests


AZURE_FORM_RECOGNIZER_ENDPOINT = os.getenv("AZURE_FORM_RECOGNIZER_ENDPOINT")
AZURE_FORM_RECOGNIZER_KEY = os.getenv("AZURE_FORM_RECOGNIZER_KEY")
AZURE_FORM_RECOGNIZER_MODEL_ID = os.getenv("AZURE_FORM_RECOGNIZER_MODEL_ID", "prebuilt-layout")


def _get_analysis_url() -> str:
    if not AZURE_FORM_RECOGNIZER_ENDPOINT:
        raise ValueError("Missing AZURE_FORM_RECOGNIZER_ENDPOINT")
    endpoint = AZURE_FORM_RECOGNIZER_ENDPOINT.rstrip("/")
    if endpoint.endswith("/formrecognizer/documentModels"):
        return f"{endpoint}/{AZURE_FORM_RECOGNIZER_MODEL_ID}:analyze?api-version=2023-07-31"
    return f"{endpoint}/formrecognizer/documentModels/{AZURE_FORM_RECOGNIZER_MODEL_ID}:analyze?api-version=2023-07-31"


def _headers(content_type: str = "application/pdf") -> Dict[str, str]:
    if not AZURE_FORM_RECOGNIZER_KEY:
        raise ValueError("Missing AZURE_FORM_RECOGNIZER_KEY")
    return {
        "Ocp-Apim-Subscription-Key": AZURE_FORM_RECOGNIZER_KEY,
        "Content-Type": content_type,
    }


def _submit_document(document_bytes: bytes, content_type: str = "application/pdf") -> str:
    url = _get_analysis_url()
    resp = requests.post(url, headers=_headers(content_type), data=document_bytes, timeout=120)
    resp.raise_for_status()
    operation_url = resp.headers.get("Operation-Location")
    if not operation_url:
        raise RuntimeError("Azure Document Intelligence did not return Operation-Location")
    return operation_url


def _poll_result(operation_url: str, timeout_seconds: int = 120, poll_interval: float = 1.5) -> Dict[str, Any]:
    import time

    deadline = time.time() + timeout_seconds
    while time.time() < deadline:
        resp = requests.get(
            operation_url,
            headers={"Ocp-Apim-Subscription-Key": AZURE_FORM_RECOGNIZER_KEY},
            timeout=60,
        )
        resp.raise_for_status()
        result = resp.json()
        status = result.get("status")
        if status in {"succeeded", "failed"}:
            return result
        time.sleep(poll_interval)
    raise TimeoutError("Timed out waiting for Azure Document Intelligence analysis result")


def _extract_text_from_lines(lines: List[Dict[str, Any]]) -> str:
    return "\n".join(line.get("content", "") for line in lines if line.get("content"))


def _kv_from_document_result(result: Dict[str, Any]) -> List[Dict[str, Any]]:
    documents = result.get("analyzeResult", {}).get("documents", []) or []
    if not documents:
        return []

    pairs: List[Dict[str, Any]] = []
    for doc in documents:
        fields = doc.get("fields", {}) or {}
        for key, field in fields.items():
            value = field.get("valueString")
            if value is None:
                for candidate in (
                    "valueDate",
                    "valueTime",
                    "valueInteger",
                    "valueNumber",
                    "valueCurrency",
                    "valueBoolean",
                ):
                    if candidate in field and field[candidate] is not None:
                        value = field[candidate]
                        break
            if value is None:
                value = field.get("content")
            confidence = field.get("confidence")
            pairs.append({"key": key, "value": value, "confidence": confidence})
    return pairs


def _kv_from_key_value_pairs(result: Dict[str, Any]) -> List[Dict[str, Any]]:
    analyze_result = result.get("analyzeResult", {})
    kv_pairs = analyze_result.get("keyValuePairs", []) or []
    pairs: List[Dict[str, Any]] = []
    for kv in kv_pairs:
        key = (kv.get("key") or {}).get("content")
        value_obj = kv.get("value") or {}
        value = value_obj.get("content")
        if key:
            pairs.append(
                {
                    "key": key,
                    "value": value,
                    "confidence": min(
                        [x for x in [(kv.get("confidence")), (kv.get("key") or {}).get("confidence"), value_obj.get("confidence")] if x is not None]
                        or [None]
                    )
                    if any(x is not None for x in [kv.get("confidence"), (kv.get("key") or {}).get("confidence"), value_obj.get("confidence")])
                    else None,
                }
            )
    return pairs


def extract_key_value_pairs(document_bytes: bytes, content_type: str = "application/pdf") -> List[Dict[str, Any]]:
    operation_url = _submit_document(document_bytes, content_type=content_type)
    result = _poll_result(operation_url)

    status = result.get("status")
    if status != "succeeded":
        error = result.get("error", {})
        raise RuntimeError(f"Azure Document Intelligence analysis failed: {error}")

    pairs = _kv_from_document_result(result)
    if not pairs:
        pairs = _kv_from_key_value_pairs(result)
    return pairs
